294	export function extractDefs<T extends schemas.$ZodType>(
295	  ctx: ToJSONSchemaContext,
296	  schema: T
297	  // params: EmitParams
298	): void {
299	  // iterate over seen map;
300	  const root = ctx.seen.get(schema);
301	
302	  if (!root) throw new Error("Unprocessed schema. This is a bug in Zod.");
303	
304	  // With `external` set, every registered schema resolves through the external branch of `makeURI`, so the root branch below produces the same ref the external branch would — this pass is identical whichever schema it is called with, and only needs to run once.
305	  if (ctx.external && ctx.sharedDefsExtractedFor === ctx.external) return;
306	
307	  // Track ids to detect duplicates across different schemas
308	  const idToSchema = new Map<string, schemas.$ZodType>();
309	  for (const entry of ctx.seen.entries()) {
310	    const id = ctx.metadataRegistry.get(entry[0])?.id;
311	    if (id) {
312	      const existing = idToSchema.get(id);
313	      if (existing && existing !== entry[0]) {
314	        throw new Error(
315	          `Duplicate schema id "${id}" detected during JSON Schema conversion. Two different schemas cannot share the same id when converted together.`
316	        );
317	      }
318	      idToSchema.set(id, entry[0]);
319	    }
320	  }
321	
322	  // returns a ref to the schema defId will be empty if the ref points to an external schema (or #)
323	  const makeURI = (entry: [schemas.$ZodType<unknown, unknown>, Seen]): { ref: string; defId?: string } => {
324	    // comparing the seen objects because sometimes multiple schemas map to the same seen object. e.g. lazy
325	
326	    // external is configured
327	    const defsSegment = ctx.target === "draft-2020-12" ? "$defs" : "definitions";
328	    if (ctx.external) {
329	      const externalId = ctx.external.registry.get(entry[0])?.id; // ?? "__shared";// `__schema${ctx.counter++}`;
330	
331	      // check if schema is in the external registry
332	      const uriGenerator = ctx.external.uri ?? ((id: string) => id);
333	      if (externalId) {
334	        return { ref: uriGenerator(externalId) };
335	      }
336	
337	      // otherwise, add to __shared
338	      const id: string = entry[1].defId ?? (entry[1].schema.id as string) ?? `schema${ctx.counter++}`;
339	      entry[1].defId = id; // set defId so it will be reused if needed
340	      return { defId: id, ref: `${uriGenerator("__shared")}#/${defsSegment}/${encodeJSONPointerSegment(id)}` };
341	    }
342	
343	    const uriPrefix = `#`;
344	    const defUriPrefix = `${uriPrefix}/${defsSegment}/`;
345	
346	    // an id-less root has nowhere to be extracted to, so it stays inline and self-references as `#`
347	    if (entry[1] === root && !entry[1].schema.id) {
348	      return { ref: uriPrefix };
349	    }
350	
351	    // self-contained schema
352	    const defId = entry[1].schema.id ?? `__schema${ctx.counter++}`;
353	    return { defId, ref: defUriPrefix + encodeJSONPointerSegment(defId) };
354	  };
355	
356	  // stored cached version in `def` property remove all properties, set $ref
357	  const extractToDef = (entry: [schemas.$ZodType<unknown, unknown>, Seen]): void => {
358	    // if the schema is already a reference, do not extract it
359	    if (entry[1].schema.$ref) {
360	      return;
361	    }
362	    const seen = entry[1];
363	    const { ref, defId } = makeURI(entry);
364	
365	    seen.def = { ...seen.schema };
366	    // defId won't be set if the schema is a reference to an external schema or if the schema is the root schema
367	    if (defId) seen.defId = defId;
368	    // wipe away all properties except $ref
369	    const schema = seen.schema;
370	    for (const key in schema) {
371	      delete schema[key];
372	    }
373	    schema.$ref = ref;
374	  };
375	
376	  // throw on cycles
377	
378	  // break cycles
379	  if (ctx.cycles === "throw") {
380	    for (const entry of ctx.seen.entries()) {
381	      const seen = entry[1];
382	      if (seen.cycle) {
383	        throw new Error(
384	          "Cycle detected: " +
385	            `#/${seen.cycle?.join("/")}/<root>` +
386	            '\n\nSet the `cycles` parameter to `"ref"` to resolve cyclical schemas with defs.'
387	        );
388	      }
389	    }
390	  }
391	
392	  // extract schemas into $defs
393	  for (const entry of ctx.seen.entries()) {
394	    const seen = entry[1];
395	
396	    // convert root schema to # $ref
397	    if (schema === entry[0]) {
398	      extractToDef(entry); // this has special handling for the root schema
399	      continue;
400	    }
401	
402	    // extract schemas that are in the external registry
403	    if (ctx.external) {
404	      const ext = ctx.external.registry.get(entry[0])?.id;
405	      if (schema !== entry[0] && ext) {
406	        extractToDef(entry);
407	        continue;
408	      }
409	    }
410	
411	    // extract schemas with `id` meta
412	    const id = ctx.metadataRegistry.get(entry[0])?.id;
413	    if (id) {
414	      extractToDef(entry);
415	      continue;
416	    }
417	
418	    // break cycles
419	    if (seen.cycle) {
420	      // any
421	      extractToDef(entry);
422	      continue;
423	    }
424	
425	    // extract reused schemas
426	    if (seen.count > 1) {
427	      if (ctx.reused === "ref") {
428	        extractToDef(entry);
429	        // biome-ignore lint:
430	        continue;
431	      }
432	    }
433	  }
434	
435	  if (ctx.external) ctx.sharedDefsExtractedFor = ctx.external;
436	}
437	
438	/** Rewrites `anyOf: [{type: "a"}, {type: "b"}]` to `type: ["a", "b"]`, which every JSON Schema draft treats as equivalent and most consumers render far better for the nullable case. Only branches that are a bare type assertion qualify — anything carrying a constraint, `$ref`, `const` or metadata is left alone. Runs after `flattenRef`, so a branch an override decorated or `$defs` extraction turned into a `$ref` is no longer bare and correctly stays in `anyOf`. `oneOf` is excluded: `integer` and `number` overlap, so "exactly one" and "at least one" are not the same there. OpenAPI 3.0 is excluded: its `type` must be a single string. */
439	function compactTypeUnion(schema: JSONSchema.BaseSchema): void {
440	  const options = schema.anyOf;
441	  if (!Array.isArray(options) || options.length === 0 || schema.type !== undefined) return;
442	
443	  const types: JSONSchema.SchemaType[] = [];
444	  for (const option of options) {
445	    if (!option || typeof option !== "object") return;
446	    // A branch that is itself a compactible union folds into this one — nested `anyOf` and a flat `type` array say the same thing. Compacting it first also makes the result independent of the order this pass walks the seen map in.
447	    compactTypeUnion(option as JSONSchema.BaseSchema);
448	    const keys = Object.keys(option);
449	    if (keys.length !== 1 || keys[0] !== "type") return;
450	    const type = (option as JSONSchema.BaseSchema).type;
451	    for (const member of Array.isArray(type) ? type : [type]) {
452	      if (typeof member !== "string") return;
453	      if (!types.includes(member)) types.push(member);
454	    }
455	  }
456	
457	  delete schema.anyOf;
458	  // A `type` array must be non-empty and unique (metaschema); a single member is spelled as a bare string.
459	  schema.type = types.length === 1 ? types[0] : types;
460	}
461	
462	/** Keywords `foldIntersection` knows how to combine. Anything else — `$ref`, `patternProperties`,
463	 * an annotation like `description` — makes a member unfoldable, so a constraint this does not
464	 * understand leaves the `allOf` alone instead of being silently dropped or misattributed. */
465	const FOLDABLE_KEYS = new Set(["type", "properties", "required", "additionalProperties"]);
466	const UNION_KEYS = ["oneOf", "anyOf"] as const;
467	
468	/** A member's constraint on a key it does not declare itself. A `catchall` states one; `false`, an absent `additionalProperties`, and the empty schema a loose object emits state nothing. */
469	function undeclaredConstraint(member: JSONSchema.ObjectSchema): JSONSchema.BaseSchema | null {
470	  const extra = member.additionalProperties;
471	  if (extra === undefined || extra === false || typeof extra !== "object" || extra === null) return null;
472	  return Object.keys(extra).length ? (extra as JSONSchema.BaseSchema) : null;
473	}
474	
475	/** Combines object members into the single object they describe together, or returns `null` if any of them carries a keyword outside {@link FOLDABLE_KEYS}. */
476	function foldObjects(members: JSONSchema._JSONSchema[]): JSONSchema.ObjectSchema | null {
477	  const objects: JSONSchema.ObjectSchema[] = [];
478	  for (const member of members) {
479	    // A boolean subschema is legal JSON Schema and carries no keywords to fold.
480	    if (typeof member !== "object" || member.type !== "object") return null;
481	    for (const key in member) {
482	      if (!FOLDABLE_KEYS.has(key)) return null;
483	    }
484	    objects.push(member as JSONSchema.ObjectSchema);
485	  }
486	
487	  const properties: Record<string, JSONSchema._JSONSchema> = {};
488	  const required = new Set<string>();
489	  for (const object of objects) {
490	    for (const key in object.properties) {
491	      // `in` would report a `__proto__` key as already present via the prototype chain and skip it.
492	      if (Object.prototype.hasOwnProperty.call(properties, key)) continue;
