// property names are always strings, and record parsing matches a numeric-string key against Number(key), so a numeric key schema is rewritten to the string form it accepts. returns a copy, since the input may be shared with other users of the key type
function stringifyPropertyNames(json: JSONSchema.BaseSchema): JSONSchema.BaseSchema {
  let out = json;
  const copy = () => (out === json ? (out = { ...json }) : out);
  if (json.type === "number" || json.type === "integer") {
    const { minimum, maximum, exclusiveMinimum, exclusiveMaximum, multipleOf, ...rest } =
      copy() as JSONSchema.NumberSchema;
    out = rest as JSONSchema.BaseSchema;
    out.type = "string";
    // an enum or const already pins the key down, so the pattern is only needed for an open number
    if (json.const === undefined && !json.enum) {
      out.pattern = (json.type === "integer" ? regexes.integer : regexes.number).source;
    }
  }
  if (typeof json.const === "number") copy().const = String(json.const);
  if (Array.isArray(json.enum) && json.enum.some((v) => typeof v === "number")) {
    copy().enum = json.enum.map((v) => (typeof v === "number" ? String(v) : v));
  }
  for (const key of ["anyOf", "oneOf"] as const) {
    const options = json[key];
    if (!Array.isArray(options)) continue;
    const mapped = options.map((o) => (typeof o === "object" && o ? stringifyPropertyNames(o) : o));
    if (mapped.some((o, i) => o !== options[i])) copy()[key] = mapped;
  }
  return out;
}

export const recordProcessor: Processor<schemas.$ZodRecord> = (schema, ctx, _json, params) => {
  const json = _json as JSONSchema.ObjectSchema;

