// property names are always strings, and record parsing matches a numeric-string key against Number(key), so a numeric key schema is rewritten to the string form it accepts. returns a copy, since the input may be shared with other users of the key type
function stringifyPropertyNames(json: JSONSchema.BaseSchema): JSONSchema.BaseSchema {
  const numeric = json.type === "number" || json.type === "integer";
  const hasNumbers =
    typeof json.const === "number" || (Array.isArray(json.enum) && json.enum.some((v) => typeof v === "number"));
  const options: Partial<Record<"anyOf" | "oneOf", JSONSchema._JSONSchema[]>> = {};
  for (const key of ["anyOf", "oneOf"] as const) {
    const branches = json[key];
    if (!Array.isArray(branches)) continue;
    const mapped = branches.map((o) => (typeof o === "object" && o ? stringifyPropertyNames(o) : o));
    if (mapped.some((o, i) => o !== branches[i])) options[key] = mapped;
  }
  if (!numeric && !hasNumbers && !options.anyOf && !options.oneOf) return json;

  const out: JSONSchema.BaseSchema = { ...json, ...options };
  if (numeric) {
    // numeric range keywords have no string form
    for (const key of ["minimum", "maximum", "exclusiveMinimum", "exclusiveMaximum", "multipleOf"]) delete out[key];
    out.type = "string";
    // an enum or const already pins the key down, so the pattern is only needed for an open number
    if (!hasNumbers) out.pattern = (json.type === "integer" ? regexes.integer : regexes.number).source;
  }
  if (typeof json.const === "number") out.const = String(json.const);
  if (Array.isArray(json.enum)) out.enum = json.enum.map((v) => (typeof v === "number" ? String(v) : v));
  return out;
}

